# Normalize locale aliases.
def locale_for(path: Path, text: str) -> str:
    m = re.search(r'\.(cs|de|el|en|es|fr|hu|id|it|ja|ko|nl|pl|pt_BR|pt|ro|tr)\.html$', path.name)
    if m:
        return m.group(1)
    m = re.search(r'<html[^>]+lang=["\']([^"\']+)', text, re.I)
    if m:
        v=m.group(1).replace('-','_')
        if v in T: return v
        if v.startswith('pt_BR'): return 'pt_BR'
        if v[:2] in T: return v[:2]
    # Existing un-suffixed files are English except household, whose legacy
    # default is Hungarian.
    return 'hu' if path.parent.name == 'household' else 'en'

def section(kind: str, loc: str) -> str:
    d=T.get(loc,T['en'])
    title=d[f'{kind}_title']
    body=d[kind]
    return f'''\n{MARKER_START}\n<section id="enila-compliance-2026" style="border:2px solid #2f6fed;border-radius:12px;padding:14px 16px;margin:16px 0 28px;background:rgba(47,111,237,.06)"><h2 style="margin-top:0">{title}</h2>{body}</section>\n{MARKER_END}\n'''

def apply(path: Path):
    text=path.read_text(encoding='utf-8')
    text=re.sub(re.escape(MARKER_START)+r'.*?'+re.escape(MARKER_END), '', text, flags=re.S)
    loc=locale_for(path,text)
    if loc not in T:
        raise RuntimeError(f'Unsupported locale {loc} in {path}')
    if path.name.startswith('privacy_policy'):
        kind='privacy'
    elif path.name.startswith('manage_consent'):
        kind='consent'
    elif path.name.startswith('terms_of_use'):
        kind='terms'
    else:
        return
    s=section(kind,loc)
    if '<body' in text.lower():
        text=re.sub(r'(<body[^>]*>)', r'\1'+s, text, count=1, flags=re.I)
    else:
        # Some generated Cryptogram documents are HTML fragments without body.
        text=s+text
    path.write_text(text,encoding='utf-8')

root=Path(__file__).resolve().parents[1]
count=0
for folder in ['clusters','cryptogram','household','magnet_grid','number_puzzle','quest_word_search','word_album']:
    for p in (root/folder).glob('*.html'):
        apply(p); count += 1
print(f'Updated {count} legal HTML files.')
